91	
92	function slugify(name: string): string {
93	  const raw = name
94	    .toLowerCase()
95	    .replace(/[^a-z0-9]+/g, "-")
96	    .replace(/^-|-$/g, "")
97	    .slice(0, 60);
98	  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
99	  if (raw.length < 3) return raw.padEnd(3, "1");
100	  return raw;
101	}
102	
103	// DB constraint only accepts 6-digit hex (#rrggbb).
104	function isValidHex(value: string): boolean {
105	  return /^#[0-9A-Fa-f]{6}$/.test(value);
106	}
