  );
}

// ---------------------------------------------------------------------------
// Main page
// ---------------------------------------------------------------------------

const CareerSettings = () => {
  const { user } = useAuth();
  const { team } = useTeam();
  const queryClient = useQueryClient();

  const teamId = team?.id ?? null;
  const userId = user?.id ?? null;

  // ----- Core form state -----
  const [companyName, setCompanyName] = useState("");
  const [slug, setSlug] = useState("");
  const [logoUrl, setLogoUrl] = useState("");
  const [brandColor, setBrandColor] = useState("#6366f1");
  const [tagline, setTagline] = useState("");
  const [about, setAbout] = useState("");
  const [isActive, setIsActive] = useState(false);
  const [configId, setConfigId] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [slugStatus, setSlugStatus] = useState<SlugStatus>("idle");
  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
  const [togglingJobId, setTogglingJobId] = useState<string | null>(null);

  // ----- Enhanced branding -----
  const [customCss, setCustomCss] = useState("");
  const [coverImageUrl, setCoverImageUrl] = useState("");
  const [fontFamily, setFontFamily] = useState("Inter");

  // ----- Culture -----
  const [cultureTitle, setCultureTitle] = useState("Why Join Us");
  const [cultureDescription, setCultureDescription] = useState("");
  const [benefits, setBenefits] = useState<Benefit[]>([]);

  // ----- Social links -----
  const [socialWebsite, setSocialWebsite] = useState("");
  const [socialLinkedin, setSocialLinkedin] = useState("");
  const [socialTwitter, setSocialTwitter] = useState("");
  const [socialInstagram, setSocialInstagram] = useState("");
  const [socialFacebook, setSocialFacebook] = useState("");

  // ----- SEO -----
  const [metaDescription, setMetaDescription] = useState("");
  const [metaKeywords, setMetaKeywords] = useState("");

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const careerPageUrl = slug ? `${window.location.origin}/careers/${slug}` : null;

  // ----- Fetch config -----
  const { data: configData, isLoading: configLoading } = useQuery({
    queryKey: ["career-page-config", teamId],
    queryFn: async () => {
      if (!teamId) return null;
      const { data, error } = await (supabase as any)
        .from("career_page_config")
        .select("*")
        .eq("team_id", teamId)
        .maybeSingle();
      if (error) throw new Error(error.message);
      return data as CareerPageConfig | null;
    },
    enabled: !!teamId,
    staleTime: 60_000,
  });

  // Populate form when config loads
  useEffect(() => {
    if (configData) {
      setConfigId(configData.id);
      setCompanyName(configData.company_name ?? "");
      setSlug(configData.slug ?? "");
      setLogoUrl(configData.logo_url ?? "");
      setBrandColor(configData.brand_color ?? "#6366f1");
      setTagline(configData.tagline ?? "");
      setAbout(configData.about ?? "");
      setIsActive(configData.is_active ?? false);
      setCustomCss(configData.custom_css ?? "");
      setCoverImageUrl(configData.cover_image_url ?? "");
      setFontFamily(configData.font_family ?? "Inter");
      setCultureTitle(configData.culture_title ?? "Why Join Us");
      setCultureDescription(configData.culture_description ?? "");
      setBenefits(Array.isArray(configData.benefits) ? (configData.benefits as Benefit[]) : []);
      const sl = ((configData.social_links ?? {}) as SocialLinks);
      setSocialWebsite(sl.website ?? "");
      setSocialLinkedin(sl.linkedin ?? "");
      setSocialTwitter(sl.twitter ?? "");
      setSocialInstagram(sl.instagram ?? "");
      setSocialFacebook(sl.facebook ?? "");
      setMetaDescription(configData.meta_description ?? "");
      setMetaKeywords(configData.meta_keywords ?? "");
      setSlugManuallyEdited(true);
    } else if (!configLoading && team?.name) {
      setCompanyName(team.name);
      const auto = slugify(team.name);
      setSlug(auto);
    }
  }, [configData, configLoading, team?.name]);

  // ----- Fetch jobs -----
  const { data: jobs = [], isLoading: jobsLoading } = useQuery({
    queryKey: ["career-jobs", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data, error } = await (supabase as any)
        .from("jobs")
        .select("id, title, location, department, employment_type, is_published, is_featured, expires_at, status, view_count, apply_count")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });
      if (error) throw new Error(error.message);
      return (data ?? []) as CareerJob[];
    },
    enabled: !!userId,
    staleTime: 30_000,
  });

  // ----- Subscriber count -----
  const { data: subscriberCount = 0 } = useQuery({
    queryKey: ["career-subscribers-count", teamId],
    queryFn: async () => {
      if (!teamId) return 0;
      const { count, error } = await (supabase as any)
        .from("career_subscribers")
        .select("id", { count: "exact", head: true })
        .eq("team_id", teamId);
      if (error) return 0;
      return (count as number) ?? 0;
    },
    enabled: !!teamId,
    staleTime: 60_000,
  });

  // ----- Slug auto-gen from company name -----
  const handleCompanyNameChange = (value: string) => {
    setCompanyName(value);
    if (!slugManuallyEdited) {
      const auto = slugify(value);
      setSlug(auto);
      triggerSlugCheck(auto);
    }
  };

  const triggerSlugCheck = useCallback(
    (value: string) => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (!value || !teamId) {
        setSlugStatus("idle");
        return;
      }
      setSlugStatus("checking");
      debounceRef.current = setTimeout(async () => {
        try {
          const { data, error } = await (supabase as any).rpc("is_career_slug_available", {
            p_slug: value,
            p_team_id: teamId,
          });
          if (error) throw error;
          setSlugStatus(data === true ? "available" : "taken");
        } catch {
          setSlugStatus("idle");
        }
      }, 600);
    },
    [teamId]
  );

  const handleSlugChange = (value: string) => {
    const clean = value.toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60);
    setSlug(clean);
    setSlugManuallyEdited(true);
    triggerSlugCheck(clean);
  };

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  // ----- Benefits helpers -----
  const addBenefit = () => {
    setBenefits((prev) => [...prev, { icon: "Star", title: "", description: "" }]);
  };

  const updateBenefit = (index: number, field: keyof Benefit, value: string) => {
    setBenefits((prev) => prev.map((b, i) => (i === index ? { ...b, [field]: value } : b)));
  };

  const removeBenefit = (index: number) => {
    setBenefits((prev) => prev.filter((_, i) => i !== index));
  };

  // ----- Save config -----
  const handleSave = async () => {
    if (!teamId) {
      toast.error("No team found. Create a team first.");
      return;
    }
    if (!companyName.trim()) {
      toast.error("Company name is required.");
      return;
    }
    if (!slug.trim()) {
      toast.error("URL slug is required.");
      return;
    }
    if (slug.length < 3) {
      toast.error("Slug must be at least 3 characters.");
      return;
    }
    if (!/^[a-z0-9]/.test(slug) || !/[a-z0-9]$/.test(slug)) {
      toast.error("Slug must start and end with a letter or number.");
      return;
    }
    if (slugStatus === "taken") {
      toast.error("That slug is already taken. Choose a different one.");
      return;
    }

    setIsSaving(true);
    try {
      const socialLinks: SocialLinks = {};
      if (socialWebsite.trim()) socialLinks.website = socialWebsite.trim();
      if (socialLinkedin.trim()) socialLinks.linkedin = socialLinkedin.trim();
      if (socialTwitter.trim()) socialLinks.twitter = socialTwitter.trim();
      if (socialInstagram.trim()) socialLinks.instagram = socialInstagram.trim();
      if (socialFacebook.trim()) socialLinks.facebook = socialFacebook.trim();

      const payload = {
        team_id: teamId,
        company_name: companyName.trim(),
        slug: slug.trim(),
        logo_url: logoUrl.trim() || null,
        brand_color: isValidHex(brandColor) ? brandColor : "#6366f1",
        tagline: tagline.trim() || null,
        about: about.trim() || null,
        is_active: isActive,
        font_family: fontFamily || "Inter",
        custom_css: customCss.trim() || null,
        cover_image_url: coverImageUrl.trim() || null,
        culture_title: cultureTitle.trim() || "Why Join Us",
        culture_description: cultureDescription.trim() || null,
        benefits: benefits,
        social_links: socialLinks,
        meta_description: metaDescription.trim() || null,
        meta_keywords: metaKeywords.trim() || null,
      };

      if (configId) {
        const { error } = await (supabase as any)
          .from("career_page_config")
          .update(payload)
          .eq("id", configId);
        if (error) throw error;
      } else {
        const { data: inserted, error } = await (supabase as any)
          .from("career_page_config")
          .insert(payload)
          .select("id")
          .single();
        if (error) throw error;
        if (inserted?.id) {
          setConfigId(inserted.id as string);
        }
      }

      toast.success("Career page saved");
      queryClient.invalidateQueries({ queryKey: ["career-page-config", teamId] });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to save career page";
      toast.error(msg);
    } finally {
      setIsSaving(false);
    }
  };

  // ----- Toggle job published -----
  const toggleJobPublished = useMutation({
    mutationFn: async ({ jobId, current }: { jobId: string; current: boolean }) => {
      const { error } = await (supabase as any)
        .from("jobs")
        .update({ is_published: !current })
        .eq("id", jobId);
      if (error) throw new Error(error.message);
      return { jobId, newValue: !current };
    },
    onMutate: ({ jobId }) => {
      setTogglingJobId(jobId);
    },
    onSuccess: ({ jobId, newValue }) => {
      queryClient.setQueryData(["career-jobs", userId], (old: CareerJob[] | undefined) =>
        (old ?? []).map((j) => (j.id === jobId ? { ...j, is_published: newValue } : j))
      );
      toast.success(newValue ? "Job published to career page" : "Job unpublished");
    },
    onError: (err: unknown) => {
      const msg = err instanceof Error ? err.message : "Failed to update job";
      toast.error(msg);
    },
    onSettled: () => {
      setTogglingJobId(null);
    },
  });

  function copyUrl() {
    if (!careerPageUrl) return;
    navigator.clipboard.writeText(careerPageUrl).then(
      () => toast.success("Link copied"),
      () => toast.error("Could not copy link")
    );
  }

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <SidebarLayout>
      <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Page header — stays above tabs */}
        <div className="flex items-start justify-between mb-1">
          <h1 className="text-2xl font-bold text-foreground">Career Page</h1>
          {isActive && careerPageUrl && (
            <div className="flex items-center gap-1.5">
              <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400 gap-1">
                <Eye className="h-3 w-3" />
                Live
              </Badge>
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={copyUrl}
                aria-label="Copy career page URL"
              >
                <Copy className="h-3.5 w-3.5" />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={() => window.open(careerPageUrl, "_blank")}
                aria-label="Open career page"
              >
                <ExternalLink className="h-3.5 w-3.5" />
              </Button>
            </div>
          )}
        </div>
        <p className="text-sm text-muted-foreground mb-6">
          Customize your public career page and manage which jobs are visible to candidates.
        </p>

        {/* Tabbed layout */}
        <Tabs defaultValue="branding" className="w-full">
          <TabsList className="w-full justify-start border-b border-border bg-transparent px-0 rounded-none h-auto mb-0">
            <TabsTrigger
              value="branding"
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent data-[state=active]:shadow-none px-4 pb-2.5 text-sm"
            >
              Branding
            </TabsTrigger>
            <TabsTrigger
              value="content"
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent data-[state=active]:shadow-none px-4 pb-2.5 text-sm"
            >
              Content
            </TabsTrigger>
            <TabsTrigger
              value="social-seo"
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent data-[state=active]:shadow-none px-4 pb-2.5 text-sm"
            >
              Social & SEO
            </TabsTrigger>
            <TabsTrigger
              value="jobs"
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent data-[state=active]:shadow-none px-4 pb-2.5 text-sm"
            >
              Jobs
            </TabsTrigger>
            <TabsTrigger
              value="advanced"
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent data-[state=active]:shadow-none px-4 pb-2.5 text-sm"
            >
              Advanced
            </TabsTrigger>
          </TabsList>

          {/* ---------------------------------------------------------------- */}
          {/* Tab 1: Branding                                                   */}
          {/* ---------------------------------------------------------------- */}
          <TabsContent value="branding" className="mt-6 space-y-6">
            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Globe className="h-4 w-4 text-primary" />
                  Identity
                </CardTitle>
                <CardDescription className="text-xs">
                  Set up your branded career page. Share the link with candidates.
                </CardDescription>
              </CardHeader>
              <CardContent>
                {configLoading ? (
                  <ConfigSkeleton />
                ) : (
                  <div className="space-y-5">
                    {/* Company name */}
                    <div className="space-y-1.5">
                      <Label htmlFor="company-name" className="text-xs font-medium">
                        Company name
                      </Label>
                      <Input
                        id="company-name"
                        placeholder="Acme Corp"
                        value={companyName}
                        onChange={(e) => handleCompanyNameChange(e.target.value)}
                        disabled={isSaving}
                      />
                    </div>

                    {/* Slug */}
                    <div className="space-y-1.5">
                      <div className="flex items-center justify-between">
                        <Label htmlFor="slug" className="text-xs font-medium">
                          URL slug
                        </Label>
                        <SlugStatusBadge status={slugStatus} />
                      </div>
                      <div className="flex items-center rounded-md border border-input bg-background ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 overflow-hidden">
                        <span className="flex items-center pl-3 pr-1 text-xs text-muted-foreground whitespace-nowrap shrink-0 select-none">
                          /careers/
                        </span>
                        <input
                          id="slug"
                          className="flex-1 py-2 pr-3 text-sm bg-transparent outline-none placeholder:text-muted-foreground"
                          placeholder="acme-corp"
                          value={slug}
                          onChange={(e) => handleSlugChange(e.target.value)}
                          disabled={isSaving}
                          spellCheck={false}
                          aria-describedby="slug-hint"
                        />
                      </div>
                      <p id="slug-hint" className="text-xs text-muted-foreground">
                        Lowercase letters, numbers, and hyphens only.
                      </p>
                    </div>

                    {/* Logo URL */}
                    <div className="space-y-1.5">
                      <Label htmlFor="logo-url" className="text-xs font-medium">
                        Logo URL
                      </Label>
                      <Input
                        id="logo-url"
                        placeholder="https://example.com/logo.png"
                        value={logoUrl}
                        onChange={(e) => setLogoUrl(e.target.value)}
                        disabled={isSaving}
                        type="url"
                      />
                    </div>

                    {/* Brand color */}
                    <div className="space-y-1.5">
                      <Label className="text-xs font-medium">Brand color</Label>
                      <div className="flex items-center gap-2">
                        <div className="relative h-9 w-14 shrink-0">
                          <input
                            type="color"
                            className="absolute inset-0 h-full w-full cursor-pointer rounded-md border border-input opacity-0"
                            value={isValidHex(brandColor) ? brandColor : "#6366f1"}
                            onChange={(e) => setBrandColor(e.target.value)}
                            disabled={isSaving}
                            aria-label="Pick brand color"
                          />
                          <div
                            className="h-full w-full rounded-md border border-input"
                            style={{ backgroundColor: isValidHex(brandColor) ? brandColor : "#6366f1" }}
                          />
                        </div>
                        <Input
                          placeholder="#6366f1"
                          value={brandColor}
                          onChange={(e) => setBrandColor(e.target.value)}
                          disabled={isSaving}
                          className="font-mono text-sm w-32"
                          maxLength={7}
                          aria-label="Brand color hex code"
                        />
                        {!isValidHex(brandColor) && brandColor.length > 0 && (
                          <span className="text-xs text-destructive">Use 6-digit hex (e.g. #6366f1)</span>
                        )}
                      </div>
                    </div>

                    {/* Cover image */}
                    <div className="space-y-1.5">
                      <Label htmlFor="cover-image-url" className="text-xs font-medium">Cover image URL</Label>
                      <Input
                        id="cover-image-url"
                        placeholder="https://example.com/office-cover.jpg"
                        value={coverImageUrl}
                        onChange={(e) => setCoverImageUrl(e.target.value)}
                        disabled={isSaving}
                        type="url"
                      />
                      <p className="text-xs text-muted-foreground">
                        Full-width hero banner shown above the company name on your career page.
                      </p>
                    </div>
                    {coverImageUrl && (
                      <div className="rounded-lg border border-border overflow-hidden">
                        <img
                          src={coverImageUrl}
                          alt="Cover preview"
                          className="w-full h-32 object-cover"
                          onError={(e) => {
                            (e.target as HTMLImageElement).style.display = "none";
                          }}
                        />
                      </div>
                    )}

                    {/* Tagline */}
                    <div className="space-y-1.5">
                      <Label htmlFor="tagline" className="text-xs font-medium">
                        Tagline
                      </Label>
                      <Input
                        id="tagline"
                        placeholder="We're building the future of work"
                        value={tagline}
                        onChange={(e) => setTagline(e.target.value)}
                        disabled={isSaving}
                        maxLength={160}
                      />
                    </div>

                    {/* Font selector */}
                    <div className="space-y-1.5">
                      <Label htmlFor="font-family" className="text-xs font-medium">Font</Label>
                      <Select value={fontFamily} onValueChange={setFontFamily} disabled={isSaving}>
                        <SelectTrigger id="font-family">
                          <SelectValue placeholder="Select a font" />
                        </SelectTrigger>
                        <SelectContent>
                          {FONT_OPTIONS.map((f) => (
                            <SelectItem key={f} value={f}>{f}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    {/* Active toggle */}
                    <div className="flex items-center justify-between rounded-lg border border-border p-3">
                      <div className="space-y-0.5">
                        <Label htmlFor="is-active" className="text-sm font-medium cursor-pointer">
                          Publish career page
                        </Label>
                        <p className="text-xs text-muted-foreground">
                          Make your career page publicly accessible to candidates.
                        </p>
                      </div>
                      <Switch
                        id="is-active"
                        checked={isActive}
                        onCheckedChange={setIsActive}
                        disabled={isSaving}
                        aria-label="Publish career page"
                      />
                    </div>

                    {/* Preview link */}
                    {isActive && careerPageUrl && (
                      <div className="flex items-center gap-2 rounded-md bg-muted/50 px-3 py-2">
                        <Globe className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                        <a
                          href={careerPageUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex-1 text-xs text-primary truncate hover:underline"
                        >
                          {careerPageUrl}
                        </a>
                        <button
                          onClick={copyUrl}
                          className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                          aria-label="Copy career page URL"
                          type="button"
                        >
                          <Copy className="h-3.5 w-3.5" />
                        </button>
                        <a
                          href={careerPageUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                          aria-label="Open in new tab"
                        >
                          <ExternalLink className="h-3.5 w-3.5" />
                        </a>
                      </div>
                    )}

                    {/* Save button */}
                    <div className="flex justify-end pt-1">
                      <Button
                        onClick={handleSave}
                        disabled={isSaving || slugStatus === "taken"}
                        className="gap-1.5"
                      >
                        {isSaving ? (
                          <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                          <Save className="h-4 w-4" />
                        )}
                        Save changes
                      </Button>
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* ---------------------------------------------------------------- */}
          {/* Tab 2: Content                                                    */}
          {/* ---------------------------------------------------------------- */}
          <TabsContent value="content" className="mt-6 space-y-6">
            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Globe className="h-4 w-4 text-primary" />
                  About
                </CardTitle>
                <CardDescription className="text-xs">
                  Tell candidates about your company, culture, and mission.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-5">
                {/* About */}
                <div className="space-y-1.5">
                  <Label htmlFor="about" className="text-xs font-medium">
                    About
                  </Label>
                  <Textarea
                    id="about"
                    placeholder="Tell candidates about your company, culture, and mission…"
                    value={about}
                    onChange={(e) => setAbout(e.target.value)}
                    disabled={isSaving}
                    rows={4}
                    className="resize-none text-sm"
                    maxLength={2000}
                  />
                </div>
              </CardContent>
            </Card>

            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Star className="h-4 w-4 text-primary" />
                  Culture & Benefits
                </CardTitle>
                <CardDescription className="text-xs">
                  Showcase your company culture and the perks you offer candidates.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-5">
                {/* Culture title */}
                <div className="space-y-1.5">
                  <Label htmlFor="culture-title" className="text-xs font-medium">Section title</Label>
                  <Input
                    id="culture-title"
                    placeholder="Why Join Us"
                    value={cultureTitle}
                    onChange={(e) => setCultureTitle(e.target.value)}
                    disabled={isSaving}
                    maxLength={80}
                  />
                </div>

                {/* Culture description */}
                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="culture-description" className="text-xs font-medium">Description</Label>
                    <span className="text-xs text-muted-foreground">{cultureDescription.length}/2000</span>
                  </div>
                  <Textarea
                    id="culture-description"
                    placeholder="Describe your culture, values, and what makes working here special…"
                    value={cultureDescription}
                    onChange={(e) => setCultureDescription(e.target.value)}
                    disabled={isSaving}
                    rows={4}
                    className="resize-none text-sm"
                    maxLength={2000}
                  />
                </div>

                {/* Benefits list */}
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <Label className="text-xs font-medium">Benefits</Label>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className="h-7 text-xs gap-1"
                      onClick={addBenefit}
                      disabled={isSaving || benefits.length >= 12}
                    >
                      <Plus className="h-3 w-3" />
                      Add benefit
                    </Button>
                  </div>
                  {benefits.length === 0 ? (
                    <div className="rounded-lg border border-dashed border-border p-6 text-center">
                      <p className="text-xs text-muted-foreground">
                        No benefits added yet. Click "Add benefit" to get started.
                      </p>
                    </div>
                  ) : (
                    <div className="space-y-3">
                      {benefits.map((benefit, index) => (
                        <div key={index} className="rounded-lg border border-border bg-muted/20 p-3 space-y-2">
                          <div className="flex items-center justify-between">
                            <span className="text-xs font-medium text-muted-foreground">Benefit {index + 1}</span>
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon"
                              className="h-6 w-6 text-muted-foreground hover:text-destructive"
                              onClick={() => removeBenefit(index)}
                              disabled={isSaving}
                              aria-label={`Remove benefit ${index + 1}`}
                            >
                              <Trash2 className="h-3 w-3" />
                            </Button>
                          </div>
                          <div className="grid grid-cols-2 gap-2">
                            <div className="space-y-1">
                              <Label className="text-xs">Lucide icon name</Label>
                              <Input
                                placeholder="e.g. Heart, Zap, Globe"
                                value={benefit.icon}
                                onChange={(e) => updateBenefit(index, "icon", e.target.value)}
                                disabled={isSaving}
                                className="h-7 text-xs"
                              />
                            </div>
                            <div className="space-y-1">
                              <Label className="text-xs">Title</Label>
                              <Input
                                placeholder="e.g. Health Insurance"
                                value={benefit.title}
                                onChange={(e) => updateBenefit(index, "title", e.target.value)}
                                disabled={isSaving}
                                className="h-7 text-xs"
                                maxLength={60}
                              />
                            </div>
                          </div>
                          <div className="space-y-1">
                            <Label className="text-xs">Description</Label>
                            <Input
                              placeholder="e.g. Full medical, dental, and vision coverage"
                              value={benefit.description}
                              onChange={(e) => updateBenefit(index, "description", e.target.value)}
                              disabled={isSaving}
                              className="h-7 text-xs"
                              maxLength={160}
                            />
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                <div className="flex justify-end">
                  <SaveButton isSaving={isSaving} onClick={handleSave} />
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* ---------------------------------------------------------------- */}
          {/* Tab 3: Social & SEO                                               */}
          {/* ---------------------------------------------------------------- */}
          <TabsContent value="social-seo" className="mt-6 space-y-6">
            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Link2 className="h-4 w-4 text-primary" />
                  Social Links
                </CardTitle>
                <CardDescription className="text-xs">
                  Add your company's social profiles. Shown in the career page footer.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-3">
                  {(
                    [
                      { Icon: Globe, label: "Website", value: socialWebsite, setter: setSocialWebsite, placeholder: "https://yourcompany.com" },
                      { Icon: Linkedin, label: "LinkedIn", value: socialLinkedin, setter: setSocialLinkedin, placeholder: "https://linkedin.com/company/yourcompany" },
                      { Icon: Twitter, label: "X / Twitter", value: socialTwitter, setter: setSocialTwitter, placeholder: "https://x.com/yourcompany" },
                      { Icon: Instagram, label: "Instagram", value: socialInstagram, setter: setSocialInstagram, placeholder: "https://instagram.com/yourcompany" },
                      { Icon: Facebook, label: "Facebook", value: socialFacebook, setter: setSocialFacebook, placeholder: "https://facebook.com/yourcompany" },
                    ] as const
                  ).map(({ Icon, label, value, setter, placeholder }) => (
                    <div key={label} className="flex items-center gap-3">
                      <Icon className="h-4 w-4 text-muted-foreground shrink-0" />
                      <Input
                        placeholder={placeholder}
                        value={value}
                        onChange={(e) => setter(e.target.value)}
                        disabled={isSaving}
                        type="url"
                        aria-label={label}
                      />
                      <span className="text-xs text-muted-foreground w-20 text-right shrink-0">{label}</span>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>

            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Globe className="h-4 w-4 text-primary" />
                  SEO
                </CardTitle>
                <CardDescription className="text-xs">
                  Improve how your career page appears in search engine results.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="meta-description" className="text-xs font-medium">Meta description</Label>
                    <span className={`text-xs ${metaDescription.length > 155 ? "text-amber-500" : "text-muted-foreground"}`}>
                      {metaDescription.length}/160
                    </span>
                  </div>
                  <Textarea
                    id="meta-description"
                    placeholder="A brief description of your career page for search engines (max 160 characters)"
                    value={metaDescription}
                    onChange={(e) => setMetaDescription(e.target.value)}
                    disabled={isSaving}
                    rows={3}
                    className="resize-none text-sm"
                    maxLength={160}
                  />
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="meta-keywords" className="text-xs font-medium">Meta keywords</Label>
                  <Input
                    id="meta-keywords"
                    placeholder="e.g. software engineer, remote jobs, startup careers"
                    value={metaKeywords}
                    onChange={(e) => setMetaKeywords(e.target.value)}
                    disabled={isSaving}
                  />
                  <p className="text-xs text-muted-foreground">Comma-separated keywords.</p>
                </div>

                <div className="flex justify-end">
                  <SaveButton isSaving={isSaving} onClick={handleSave} />
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* ---------------------------------------------------------------- */}
          {/* Tab 4: Jobs                                                       */}
          {/* ---------------------------------------------------------------- */}
          <TabsContent value="jobs" className="mt-6 space-y-6">
            {/* Subscribers count card */}
            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Users className="h-4 w-4 text-primary" />
                  Email Subscribers
                </CardTitle>
                <CardDescription className="text-xs">
                  Candidates who subscribed to job alerts from your career page.
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="flex items-center gap-4 rounded-lg border border-border bg-muted/20 p-4">
                  <div className="rounded-full bg-primary/10 p-2.5 shrink-0">
                    <Users className="h-5 w-5 text-primary" />
                  </div>
                  <div>
                    <p className="text-2xl font-bold text-foreground leading-none">{subscriberCount}</p>
                    <p className="text-xs text-muted-foreground mt-1">
                      {subscriberCount === 1 ? "subscriber" : "subscribers"} waiting for new job alerts
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Published jobs table */}
            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Globe className="h-4 w-4 text-primary" />
                  Published Jobs
                </CardTitle>
                <CardDescription className="text-xs">
                  Toggle which jobs appear on your career page. Featured jobs appear first.
                </CardDescription>
              </CardHeader>
              <CardContent className="p-0">
                {jobsLoading ? (
                  <JobsSkeleton />
                ) : jobs.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-14 space-y-3 text-center px-4">
                    <div className="rounded-xl bg-muted/50 p-4">
                      <Globe className="h-7 w-7 text-muted-foreground/40" />
                    </div>
                    <div className="space-y-1">
                      <p className="text-sm font-medium text-foreground">No jobs yet</p>
                      <p className="text-sm text-muted-foreground max-w-xs">
                        Create a job posting from the dashboard to list it on your career page.
                      </p>
                    </div>
                  </div>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead className="text-xs">Title</TableHead>
                        <TableHead className="text-xs hidden sm:table-cell">Location</TableHead>
                        <TableHead className="text-xs hidden md:table-cell">Expires</TableHead>
                        <TableHead className="text-xs hidden lg:table-cell">Analytics</TableHead>
                        <TableHead className="text-xs text-right pr-4">Published</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {jobs.map((job) => {
                        const isToggling = togglingJobId === job.id;
                        const published = job.is_published ?? false;
                        const isExpired = job.expires_at
                          ? new Date(job.expires_at) < new Date()
                          : false;
                        return (
                          <TableRow key={job.id}>
                            <TableCell className="text-sm font-medium max-w-[200px]">
                              <div className="flex items-center gap-1.5">
                                <span className="truncate" title={job.title ?? ""}>
                                  {job.title || <span className="text-muted-foreground italic">Untitled</span>}
                                </span>
                                {job.is_featured && (
                                  <Badge variant="secondary" className="text-[10px] px-1 py-0 gap-0.5 shrink-0">
                                    <Star className="h-2.5 w-2.5" />
                                    Featured
                                  </Badge>
                                )}
                              </div>
                              {job.employment_type && (
                                <span className="text-xs text-muted-foreground">{job.employment_type}</span>
                              )}
                            </TableCell>
                            <TableCell className="text-sm text-muted-foreground hidden sm:table-cell">
                              {job.location || "—"}
                            </TableCell>
                            <TableCell className="hidden md:table-cell">
                              {job.expires_at ? (
                                <span className={`text-xs ${isExpired ? "text-destructive" : "text-muted-foreground"}`}>
                                  {isExpired ? "Expired" : new Date(job.expires_at).toLocaleDateString()}
                                </span>
                              ) : (
                                <span className="text-xs text-muted-foreground">—</span>
                              )}
                            </TableCell>
                            <TableCell className="hidden lg:table-cell">
                              <span className="text-xs text-muted-foreground whitespace-nowrap">
                                {(job.view_count ?? 0).toLocaleString()} views
                                {" · "}
                                {(job.apply_count ?? 0).toLocaleString()} applied
                              </span>
                            </TableCell>
                            <TableCell className="text-right pr-4">
                              {isToggling ? (
                                <div className="flex justify-end">
                                  <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                                </div>
                              ) : (
                                <Switch
                                  checked={published}
                                  onCheckedChange={() =>
                                    toggleJobPublished.mutate({ jobId: job.id, current: published })
                                  }
                                  disabled={isToggling}
                                  aria-label={`${published ? "Unpublish" : "Publish"} ${job.title ?? "job"}`}
                                />
                              )}
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* ---------------------------------------------------------------- */}
          {/* Tab 5: Advanced                                                   */}
          {/* ---------------------------------------------------------------- */}
          <TabsContent value="advanced" className="mt-6 space-y-6">
            {/* Custom CSS */}
            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Code2 className="h-4 w-4 text-primary" />
                  Custom CSS
                </CardTitle>
                <CardDescription className="text-xs">
                  Advanced — inject custom styles into your career page.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-start gap-2 rounded-md bg-yellow-50 dark:bg-yellow-950/20 border border-yellow-200 dark:border-yellow-800/40 px-3 py-2.5">
                  <Info className="h-3.5 w-3.5 text-yellow-600 dark:text-yellow-400 shrink-0 mt-0.5" />
                  <p className="text-xs text-yellow-700 dark:text-yellow-400">
                    Custom CSS is injected directly into your career page. Incorrect styles may break the page layout.
                  </p>
                </div>
                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="custom-css" className="text-xs font-medium">CSS</Label>
                    <span className={`text-xs ${customCss.length > 4800 ? "text-amber-500" : "text-muted-foreground"}`}>
                      {customCss.length}/5000
                    </span>
                  </div>
                  <Textarea
                    id="custom-css"
                    placeholder={`.career-hero { background: linear-gradient(135deg, #667eea, #764ba2); }\n.job-card { border-radius: 12px; }`}
                    value={customCss}
                    onChange={(e) => setCustomCss(e.target.value)}
                    disabled={isSaving}
                    rows={8}
                    className="resize-none text-xs font-mono"
                    maxLength={5000}
                  />
                </div>
                <div className="flex justify-end">
                  <SaveButton isSaving={isSaving} onClick={handleSave} />
                </div>
              </CardContent>
            </Card>

            {/* Custom Domain (Coming Soon) */}
            <Card className="border border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Link2 className="h-4 w-4 text-primary" />
                  Custom Domain
                  <Badge variant="secondary" className="text-[10px] px-1.5 py-0 h-4 ml-1">
                    Coming soon
                  </Badge>
                </CardTitle>
                <CardDescription className="text-xs">
                  Host your career page on your own domain (e.g.{" "}
                  <span className="font-mono">careers.yourcompany.com</span>) instead of the default Rankora subdomain.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <ul className="space-y-2">
                  {[
                    "Point any subdomain or root domain to Rankora via CNAME",
                    "Automatic SSL certificate provisioning",
                    "Branded URL in all candidate-facing email links",
                    "No Rankora branding on custom domain pages",
                    "Domain verification dashboard with DNS health check",
                  ].map((f) => (
                    <li key={f} className="flex items-start gap-2.5 text-sm text-muted-foreground">
                      <CheckCircle2 className="h-4 w-4 text-primary/60 shrink-0 mt-0.5" />
                      <span>{f}</span>
                    </li>
                  ))}
                </ul>
                <div className="pt-1">
                  <Button
                    size="sm"
                    variant="outline"
                    className="gap-1.5"
                    onClick={() =>
                      toast.success("We've noted your interest. You'll be first to know when Custom Domain launches.")
                    }
                  >
                    Request Early Access
                  </Button>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </main>
    </SidebarLayout>
  );
};

export default CareerSettings;
